mapper.select:
SELECT custcd AS custcd, custcd AS code, custnm AS custnm, ceo AS ceo, telno AS telno, address AS address FROM haba020t_tbl WHERE cmpycd = #{cmpycd}
AND (custnm LIKE CONCAT('%', #{keyword}, '%') OR custcd LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY custnm

SELECT itemcd AS itemcd, itemcd AS code, itemnm AS itemnm, itsize AS itsize, unit AS unit, omprice AS uprc FROM hsba010t_tbl WHERE cmpycd = #{cmpycd}
AND (itemnm LIKE CONCAT('%', #{keyword}, '%') OR itemcd LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY itemnm

choose.when:
SELECT code AS code, cdnm AS codenm, remark AS remark, dspord FROM hsba900t_tbl WHERE useyn = 'Y' and cmpycd = #{cmpycd}
AND cdgbn = #{gbncd}
AND (cdnm LIKE CONCAT('%', #{keyword}, '%') OR code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY dspord
